\draw (O) circle (2);\draw (A)--(B)--(C)--cycle;\fill (O) circle (0.035);
\node[left] at (A) {$A$};\node[right] at (C) {$C$};\node[above right] at (B) {$B$};\node[below] at (O) {$O$};
